#!/usr/bin/env bash
# Builds repo/ deterministically. Usage: ./setup.sh [absolute-output-dir]
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
source "$here/../../fixture-lib.sh"
out="${1:-$here/repo}"
ledger_base "$out"
# regenerated schema files: committed once, then rewritten (timestamp header only)
mkdir -p ledgerkit/_gen
for i in $(seq -w 1 60); do put "ledgerkit/_gen/schema_$i.py" <<J
# generated by gen-schemas 1.0 at 2026-09-17T09:45 -- do not edit
FIELDS = ["id", "amount", "date"]
J
done
git add ledgerkit/_gen; GIT_AUTHOR_DATE="2026-09-17T09:45:00" GIT_COMMITTER_DATE="2026-09-17T09:45:00" git commit -q -m "chore: generate schemas"
for i in $(seq -w 1 60); do put "ledgerkit/_gen/schema_$i.py" <<J
# generated by gen-schemas 1.0 at 2026-09-17T15:05 -- do not edit
FIELDS = ["id", "amount", "date"]
J
done
stamp 202609171505 ledgerkit/_gen/*.py
